cd /home/user/rork-app && python3 << 'PYEOF'
import os, json

EXCLUDE_DIRS = {
    'node_modules', 'node_modules-full', '.git', '.rork',
    '__pycache__', '.tmp-frames', '.tmp-ivx-frames',
    'dist', 'home'
}
EXCLUDE_FILES = {
    '.gitignore', '.gitattributes', '.gitmodules',
    'bun.lock', 'GATE4_RORK_HISTORY_PURGE.md',
    'PROJECT_SEPARATION.md', 'IVX_CRITICAL_FILES_MANIFEST.json',
}
EXCLUDE_PREFIXES = (
    'ivx_20step_', 'ivx_acceptance_test', 'phase1_test',
    'cert_test.py', 'web_qa_',
)
EXCLUDE_EXACT = {
    '.env.example', '.tmp-frames', '.tmp-ivx-frames',
}

files = []
for root, dirs, fnames in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in EXCLUDE_DIRS]
    for f in fnames:
        fp = os.path.join(root, f)
        rel = fp[2:]  # strip ./
        if rel in EXCLUDE_FILES:
            continue
        if any(rel.startswith(p) for p in EXCLUDE_PREFIXES):
            continue
        if rel in EXCLUDE_EXACT:
            continue
        # Skip binary/image files
        if rel.endswith(('.png', '.jpg', '.jpeg', '.gif', '.webp', '.ico')):
            continue
        files.append(rel)

files.sort()
with open('/tmp/local_files.json', 'w') as fh:
    json.dump(files, fh)
print(f"LOCAL_FILES: {len(files)}")
PYEOF

